145	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
146	        ownerFieldsDto.setAddress(this.addressNormalizer.normalize(ownerFieldsDto.getAddress()));
147	        this.ownerFieldsValidator.validate(ownerFieldsDto);
148	        HttpHeaders headers = new HttpHeaders();
149	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
150	        owner.setTelephone(this.telephoneNormalizer.normalize(owner.getTelephone()));
151	        owner.setEmail(this.emailNormalizer.normalize(owner.getEmail()));
152	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
153	        owner.setRegistrationDate(this.businessDayResolver.toBusinessDay(effectiveDate));
154	        long ownersRegisteredToday = this.clinicService.countOwnersRegisteredOn(owner.getRegistrationDate());
155	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
156	            throw new OwnerDailyRegistrationLimitExceededException(owner.getRegistrationDate(), MAX_OWNERS_PER_DAY);
157	        }
158	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
159	        if (!this.clinicService.findOwnerByTelephone(owner.getTelephone()).isEmpty()) {
160	            throw new DuplicateOwnerTelephoneException(owner.getTelephone());
161	        }
162	        if (this.clinicService.countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
