169	        }
170	        this.clinicService.saveOwner(owner);
171	        this.ownerAuditLogger.logCreated(owner);
172	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
173	        headers.setLocation(UriComponentsBuilder.newInstance()
174	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
